-- T-98: boards and their members (data-model.md `boards`, ADR-0007).
-- Board ids are generated by the client (UUIDv7) so boards can be created offline; the server
-- scopes them to their owner. `version` is the board's change cursor (bumped on every change).

CREATE SCHEMA IF NOT EXISTS boards;

CREATE TABLE boards.boards (
    id              UUID PRIMARY KEY,
    owner_id        UUID NOT NULL REFERENCES identity.accounts (id) ON DELETE CASCADE,
    title           TEXT NOT NULL CHECK (char_length(title) BETWEEN 1 AND 400),
    -- Registry reference `{id, version, params}` (validated by the API); NULL = default backdrop.
    backdrop        JSONB NULL,
    version         BIGINT NOT NULL DEFAULT 1 CHECK (version >= 1),
    schema_version  SMALLINT NOT NULL DEFAULT 1,
    created_at      TIMESTAMPTZ NOT NULL,
    updated_at      TIMESTAMPTZ NOT NULL,
    deleted_at      TIMESTAMPTZ NULL
);
CREATE INDEX boards_owner_live ON boards.boards (owner_id) WHERE deleted_at IS NULL;

-- One row per member, the owner included (role `owner`). Collaborators join only by accepting
-- an invitation (T-106).
CREATE TABLE boards.board_members (
    board_id    UUID NOT NULL REFERENCES boards.boards (id) ON DELETE CASCADE,
    user_id     UUID NOT NULL REFERENCES identity.accounts (id) ON DELETE CASCADE,
    role        TEXT NOT NULL CHECK (role IN ('owner', 'collaborator')),
    invitation_id UUID NULL,
    created_at  TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (board_id, user_id)
);
CREATE INDEX board_members_user ON boards.board_members (user_id);
CREATE UNIQUE INDEX board_members_one_owner ON boards.board_members (board_id) WHERE role = 'owner';
